IF v_collision_count > 0 THEN RAISE EXCEPTION 'gc_quarantine_orphans_bounded: % cross-dim (tenant_id, collection, chash) collision(s) at quarantine target % for tenant=%, origin collection=%. Sample chashes: %. Refusing to overwrite.', v_collision_count, p_quarantine_collection, p_tenant_id, p_collection, v_collision_sample USING ERRCODE = 'unique_violation'; END IF;
v_seg := string_to_array(p_quarantine_collection, '__'); INSERT INTO nexus.catalog_collections (tenant_id, name, content_type, owner_id, embedding_model, model_version, lifecycle_state) VALUES ( p_tenant_id, p_quarantine_collection, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[1] ELSE 'unknown' END, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[2] ELSE p_tenant_id END, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[3] ELSE 'bge-base-en-v15-768' END, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[4] ELSE '' END, 'quarantine' ) ON CONFLICT (tenant_id, name) DO NOTHING;
