changeSet.sql:
ALTER TABLE nexus.catalog_collections NO FORCE ROW LEVEL SECURITY;
DO $$ DECLARE v_corrected_from_origin bigint; v_corrected_content_only bigint; BEGIN -- Candidates: quarantine-shaped name (prefix "quarantine-" or suffix -- "__quarantine") whose content_type still shows the shipped defect's -- signature -- a literal "quarantine-" prefix, or the 'unknown' -- fallback a genuinely unparseable name would have produced under the -- SAME buggy string_to_array logic (array_length <> 4). CREATE TEMP TABLE _h008_walk ON COMMIT DROP AS SELECT c.tenant_id, c.name, CASE WHEN c.name LIKE 'quarantine-%' THEN regexp_replace(c.name, '^quarantine-', '') WHEN c.name ~ '__quarantine$' THEN regexp_replace(c.name, '__quarantine$', '') END AS origin_name FROM nexus.catalog_collections c WHERE (c.name LIKE 'quarantine-%' OR c.name ~ '__quarantine$') AND (c.content_type LIKE 'quarantine-%' OR c.content_type = 'unknown');
-- Branch 1: the derived origin sibling IS registered -- copy every -- attribute verbatim and stamp lifecycle_state = 'quarantine' -- (correcting content_type is the only thing in question here; the -- row's own quarantine identity, by name shape, is never in doubt). UPDATE nexus.catalog_collections c SET content_type = o.content_type, owner_id = o.owner_id, embedding_model = o.embedding_model, model_version = o.model_version, dimension = o.dimension, lifecycle_state = 'quarantine' FROM _h008_walk w JOIN nexus.catalog_collections o ON o.tenant_id = w.tenant_id AND o.name = w.origin_name WHERE c.tenant_id = w.tenant_id AND c.name = w.name; GET DIAGNOSTICS v_corrected_from_origin = ROW_COUNT; RAISE NOTICE 'hygiene-008-2: % quarantine-shaped row(s) corrected from a registered origin sibling', v_corrected_from_origin;
-- Branch 2: no registered origin sibling to copy from -- strip a -- literal "quarantine-" prefix from content_type when that leaves a -- non-empty value (the best correction available without a real -- sibling to copy from); a bare 'unknown' content_type has no such -- prefix and is left exactly as it is. lifecycle_state is NEVER -- touched here -- there is no known-good sibling attesting this row's -- true state. UPDATE nexus.catalog_collections c SET content_type = regexp_replace(c.content_type, '^quarantine-', '') FROM _h008_walk w WHERE c.tenant_id = w.tenant_id AND c.name = w.name AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_collections o WHERE o.tenant_id = w.tenant_id AND o.name = w.origin_name ) AND regexp_replace(c.content_type, '^quarantine-', '') <> ''; GET DIAGNOSTICS v_corrected_content_only = ROW_COUNT; RAISE NOTICE 'hygiene-008-2: % quarantine-shaped row(s) with no registered origin sibling had a literal quarantine- content_type prefix stripped', v_corrected_content_only;
END $$;
ALTER TABLE nexus.catalog_collections FORCE ROW LEVEL SECURITY;
